import { activityStateToAgentState, type TerminalActivityState } from "./activity";
import type { AgentState } from "./types";

const AGENT_SPINNER_RE = /[\u2800-\u28FF✦✳⏲]/u;
const ANSI_ESCAPE_RE = /\u001b\[[0-9;]*[a-zA-Z]/g;
const CONTROL_CHARS_RE = /[\x00-\x1f\x7f]/g;
const LEADING_ACTIVITY_GLYPHS_RE = /^[\u2800-\u28FF✦✳⏲✋◇\s*•\-–—|/\\~]+/u;

const WAITING_RE = /\b(waiting|awaiting|needs? input|requires? input|permission|action required|approval|confirm(?:ation)?|user input)\b/i;
const DONE_RE = /\b(done|completed?|finished|idle)\b/i;
const DONE_GLYPH_RE = /^[◇*](?:\s|$)/u;
const WORKING_RE = /\b(working|thinking|running|executing|processing)\b/i;

const SHELL_ONLY_RE = /^(?:-?(?:zsh|bash|fish|sh|csh|tcsh|dash|ksh|login|tmux|screen))$/i;

export interface KnownAgent {
  pattern: RegExp;
  type: string;
  name: string;
}

export const KNOWN_AGENT_MATCHERS: KnownAgent[] = [
  { pattern: /\b(?:agy|antigravity)\b/i, type: "antigravity", name: "Antigravity" },
  { pattern: /\bomo\b/i, type: "omo", name: "OMO" },
  { pattern: /\b(?:claude code|claude)\b/i, type: "claude", name: "Claude Code" },
  { pattern: /\bcodex\b/i, type: "codex", name: "Codex" },
  { pattern: /\bopencode\b/i, type: "opencode", name: "OpenCode" },
  { pattern: /\b(?:omp|oh-my-pi)\b/i, type: "omp", name: "OMP" },
  { pattern: /\bpi\b/i, type: "pi", name: "Pi" },
  { pattern: /\baider\b/i, type: "aider", name: "Aider" },
  { pattern: /\bcursor\b/i, type: "cursor", name: "Cursor" },
  { pattern: /\bgemini\b/i, type: "gemini", name: "Gemini CLI" },
  { pattern: /\bgrok\b/i, type: "grok", name: "Grok" },
  { pattern: /\bdevin\b/i, type: "devin", name: "Devin" },
  { pattern: /\bdroid\b/i, type: "droid", name: "Droid" },
  { pattern: /\bhermes\b/i, type: "hermes", name: "Hermes" },
  { pattern: /\bkimi\b/i, type: "kimi", name: "Kimi" },
  { pattern: /\bgoose\b/i, type: "goose", name: "Goose" },
  { pattern: /\bcline\b/i, type: "cline", name: "Cline" },
  { pattern: /\bcodebuff\b/i, type: "codebuff", name: "Codebuff" },
  { pattern: /\brovo\b/i, type: "rovo", name: "Rovo" },
  { pattern: /\bopenclaw\b/i, type: "openclaw", name: "OpenClaw" },
  { pattern: /\bcopilot\b/i, type: "copilot", name: "GitHub Copilot" },
  { pattern: /\bmimo\b/i, type: "mimo", name: "Mimo" },
];

export type ParsedAgentInfo = {
  isAgent: boolean;
  agentType: string;
  name: string;
  task: string;
  state: AgentState;
  displayTitle: string;
};

export function normalizeTerminalTitle(rawTitle: string): string {
  if (!rawTitle) return "";
  return rawTitle
    .replace(/^\u001b\][0-9];|\u0007$/g, "")
    .replace(ANSI_ESCAPE_RE, "")
    .replace(CONTROL_CHARS_RE, "")
    .trim();
}

export function containsAgentSpinnerGlyph(rawTitle: string): boolean {
  return AGENT_SPINNER_RE.test(normalizeTerminalTitle(rawTitle));
}

export function classifyTerminalTitleActivity(rawTitle: string): TerminalActivityState | null {
  const normalized = normalizeTerminalTitle(rawTitle);
  if (!normalized) return null;

  if (normalized.includes("✋") || WAITING_RE.test(normalized)) return "waiting";
  if (DONE_RE.test(normalized) || DONE_GLYPH_RE.test(normalized)) return "done";
  if (containsAgentSpinnerGlyph(normalized) || WORKING_RE.test(normalized)) return "working";

  const cleaned = stripLeadingActivityGlyphs(normalized);

  if (SHELL_ONLY_RE.test(cleaned)) {
    return null;
  }

  // An agent-name-only title carries no activity signal: the agent is present
  // but idle, so it must NOT be classified as working (Orca parity).
  return null;
}

function resolveParsedAgentState(normalized: string): AgentState {
  const activity = classifyTerminalTitleActivity(normalized);
  // No signal means idle: report neutral "starting" so no indicator spins.
  return activity ? activityStateToAgentState(activity) : "starting";
}

export function stripLeadingActivityGlyphs(title: string): string {
  return title.replace(LEADING_ACTIVITY_GLYPHS_RE, "").trim();
}

export function parseAgentTitle(rawTitle: string): ParsedAgentInfo | null {
  const normalized = normalizeTerminalTitle(rawTitle);
  if (!normalized) return null;

  const lower = normalized.toLowerCase();
  const withoutSpinner = stripLeadingActivityGlyphs(normalized);

  if (
    normalized.startsWith("✳ ") ||
    normalized === "✳" ||
    lower.startsWith("claude") ||
    lower.includes("claude code")
  ) {
    return {
      isAgent: true,
      agentType: "claude",
      name: "Claude Code",
      task: withoutSpinner || "Claude Code",
      state: resolveParsedAgentState(normalized),
      displayTitle: normalized,
    };
  }

  for (const agent of KNOWN_AGENT_MATCHERS) {
    if (agent.pattern.test(lower)) {
      const taskPattern = new RegExp(`^(?:${agent.pattern.source})\\s*[:\\-–—|]?\\s*(.*)$`, "i");
      const taskMatch = taskPattern.exec(withoutSpinner);
      const extractedTask = taskMatch && taskMatch[1]?.trim() ? taskMatch[1].trim() : withoutSpinner;

      return {
        isAgent: true,
        agentType: agent.type,
        name: agent.name,
        task: extractedTask || agent.name,
        state: resolveParsedAgentState(normalized),
        displayTitle: normalized,
      };
    }
  }

  if (containsAgentSpinnerGlyph(normalized) && withoutSpinner) {
    return {
      isAgent: true,
      agentType: "generic",
      name: withoutSpinner.split(/\s+/)[0] || "Agent",
      task: withoutSpinner,
      state: resolveParsedAgentState(normalized),
      displayTitle: normalized,
    };
  }

  return {
    isAgent: false,
    agentType: "terminal",
    name: normalized,
    task: normalized,
    state: "working",
    displayTitle: normalized,
  };
}

export function formatTabLabelFromTitle(title: string, fallbackLabel: string): string {
  const normalized = normalizeTerminalTitle(title);
  if (!normalized) return fallbackLabel;

  const cleaned = stripLeadingActivityGlyphs(normalized);
  return cleaned || normalized;
}

import { describe, expect, it } from "vitest";

import {
  classifyTerminalTitleActivity,
  containsAgentSpinnerGlyph,
  formatTabLabelFromTitle,
  normalizeTerminalTitle,
  parseAgentTitle,
} from "./agentTitle";

describe("agentTitle parser & normalizer", () => {
  it("normalizes terminal title strings by stripping control characters and trimming", () => {
    expect(normalizeTerminalTitle("  \x1b[0m\x07hello world  ")).toBe("hello world");
    expect(normalizeTerminalTitle("\x1b]0;agy: running task\x07")).toBe("agy: running task");
    expect(normalizeTerminalTitle("")).toBe("");
  });

  describe("spinner detection and working state classification", () => {
    it("detects various braille and symbolic spinner glyphs", () => {
      expect(containsAgentSpinnerGlyph("⠋ omo: starting")).toBe(true);
      expect(containsAgentSpinnerGlyph("⠹ agy: optimizing")).toBe(true);
      expect(containsAgentSpinnerGlyph("✦ antigravity: analyzing")).toBe(true);
      expect(containsAgentSpinnerGlyph("✳ claude code: thinking")).toBe(true);
      expect(containsAgentSpinnerGlyph("⏲ aider: applying patch")).toBe(true);
      expect(containsAgentSpinnerGlyph("bash")).toBe(false);
    });

    it("classifies spinner-prefixed and working titles as working activity", () => {
      expect(classifyTerminalTitleActivity("⠋ omo: refactoring layout")).toBe("working");
      expect(classifyTerminalTitleActivity("✦ codex: reviewing diffs")).toBe("working");
      expect(classifyTerminalTitleActivity("✳ claude code - analyzing tests")).toBe("working");
      expect(classifyTerminalTitleActivity("⏲ aider: applying patch")).toBe("working");
      expect(classifyTerminalTitleActivity("omo: working")).toBe("working");
    });
  });

  describe("waiting and done state precedence", () => {
    it("gives waiting semantics precedence over spinner glyphs", () => {
      expect(classifyTerminalTitleActivity("✋ omo: permission required")).toBe("waiting");
      expect(classifyTerminalTitleActivity("✦ codex: needs input")).toBe("waiting");
      expect(classifyTerminalTitleActivity("⠹ agy: waiting for user confirmation")).toBe("waiting");
      expect(classifyTerminalTitleActivity("antigravity: action required")).toBe("waiting");
    });

    it("gives done semantics precedence over spinner glyphs and other activity", () => {
      expect(classifyTerminalTitleActivity("✳ claude code: done")).toBe("done");
      expect(classifyTerminalTitleActivity("⠋ omo: completed")).toBe("done");
      expect(classifyTerminalTitleActivity("◇ agy finished")).toBe("done");
      expect(classifyTerminalTitleActivity("* codex result")).toBe("done");
      expect(classifyTerminalTitleActivity("zsh /repo")).toBeNull();
    });
  });

  describe("agy / antigravity agent detection and state parsing", () => {
    it("detects agy shorthand with working, waiting, and done states", () => {
      const working = parseAgentTitle("⠹ agy: running task");
      expect(working).not.toBeNull();
      expect(working?.isAgent).toBe(true);
      expect(working?.agentType).toBe("antigravity");
      expect(working?.name).toBe("Antigravity");
      expect(working?.task).toBe("running task");
      expect(working?.state).toBe("working");

      const waiting = parseAgentTitle("agy: waiting for user approval");
      expect(waiting?.isAgent).toBe(true);
      expect(waiting?.agentType).toBe("antigravity");
      expect(waiting?.state).toBe("waiting");

      const done = parseAgentTitle("◇ agy: done");
      expect(done?.isAgent).toBe(true);
      expect(done?.agentType).toBe("antigravity");
      expect(done?.state).toBe("exited");
    });

    it("detects full antigravity name with working, waiting, and done states", () => {
      const working = parseAgentTitle("✦ antigravity: executing tools");
      expect(working?.isAgent).toBe(true);
      expect(working?.agentType).toBe("antigravity");
      expect(working?.name).toBe("Antigravity");
      expect(working?.state).toBe("working");

      const waiting = parseAgentTitle("antigravity: needs input");
      expect(waiting?.isAgent).toBe(true);
      expect(waiting?.state).toBe("waiting");
    });
  });

  describe("OMO agent parsing", () => {
    it("detects OMO agent with working, waiting, and done states", () => {
      const working = parseAgentTitle("⠋ omo: refactoring layout components");
      expect(working).not.toBeNull();
      expect(working?.isAgent).toBe(true);
      expect(working?.agentType).toBe("omo");
      expect(working?.name).toBe("OMO");
      expect(working?.task).toBe("refactoring layout components");
      expect(working?.state).toBe("working");

      const waiting = parseAgentTitle("omo: waiting for user confirmation");
      expect(waiting).not.toBeNull();
      expect(waiting?.isAgent).toBe(true);
      expect(waiting?.state).toBe("waiting");

      const done = parseAgentTitle("✳ omo: done");
      expect(done?.state).toBe("exited");
    });
  });

  describe("other agents & non-agent processes", () => {
    it("detects Claude Code, Codex, and other agents", () => {
      const claude = parseAgentTitle("✳ claude code - analyzing tests");
      expect(claude?.isAgent).toBe(true);
      expect(claude?.name).toBe("Claude Code");

      const codex = parseAgentTitle("⠋ codex: generating code");
      expect(codex?.isAgent).toBe(true);
      expect(codex?.name).toBe("Codex");
      expect(codex?.state).toBe("working");

      const opencode = parseAgentTitle("opencode task");
      expect(opencode?.isAgent).toBe(true);
      expect(opencode?.name).toBe("OpenCode");
    });

    it("handles non-agent processes", () => {
      const vim = parseAgentTitle("vim src/App.tsx");
      expect(vim?.isAgent).toBe(false);
      expect(vim?.name).toBe("vim src/App.tsx");
    });
  });

  describe("idle agent-name-only titles", () => {
    it("does not classify bare agent names as working", () => {
      expect(classifyTerminalTitleActivity("agy")).toBeNull();
      expect(classifyTerminalTitleActivity("antigravity")).toBeNull();
      expect(classifyTerminalTitleActivity("omo")).toBeNull();
      expect(classifyTerminalTitleActivity("claude code")).toBeNull();
    });

    it("reports a neutral state for an idle agent title", () => {
      const idle = parseAgentTitle("agy");
      expect(idle?.isAgent).toBe(true);
      expect(idle?.agentType).toBe("antigravity");
      expect(idle?.state).not.toBe("working");
    });
  });

  describe("tab label formatting", () => {
    it("formats clean tab labels from title", () => {
      expect(formatTabLabelFromTitle("⠋ omo: test suite", "main")).toBe("omo: test suite");
      expect(formatTabLabelFromTitle("⠹ agy: optimization pass", "main")).toBe("agy: optimization pass");
      expect(formatTabLabelFromTitle("✋ codex: needs input", "main")).toBe("codex: needs input");
      expect(formatTabLabelFromTitle("⏲ aider: fixing", "main")).toBe("aider: fixing");
      expect(formatTabLabelFromTitle("", "main")).toBe("main");
    });
  });
});

import type { AgentState } from "./types";

export type TerminalActivityState = "working" | "waiting" | "done";

export type TerminalActivity = {
  state: TerminalActivityState;
  title: string;
  isAgent: boolean;
  agentType?: string;
};

export type ActivitySummary = {
  workingCount: number;
  waitingCount: number;
  doneCount: number;
  runningCount: number;
  hasWorking: boolean;
  hasWaiting: boolean;
  hasDone: boolean;
  hasUnread: boolean;
};

export type ActivityIndicatorState = TerminalActivityState | "unread" | null;

export function summarizeActivities(
  activities: Iterable<TerminalActivity>,
  hasUnread = false,
): ActivitySummary {
  let workingCount = 0;
  let waitingCount = 0;
  let doneCount = 0;

  for (const activity of activities) {
    if (activity.state === "working") workingCount += 1;
    else if (activity.state === "waiting") waitingCount += 1;
    else doneCount += 1;
  }

  return {
    workingCount,
    waitingCount,
    doneCount,
    runningCount: workingCount,
    hasWorking: workingCount > 0,
    hasWaiting: waitingCount > 0,
    hasDone: doneCount > 0,
    hasUnread,
  };
}

export function combineActivitySummaries(
  summaries: Iterable<ActivitySummary>,
  hasUnread = false,
): ActivitySummary {
  let workingCount = 0;
  let waitingCount = 0;
  let doneCount = 0;
  let unread = hasUnread;

  for (const summary of summaries) {
    workingCount += summary.workingCount;
    waitingCount += summary.waitingCount;
    doneCount += summary.doneCount;
    unread ||= summary.hasUnread;
  }

  return {
    workingCount,
    waitingCount,
    doneCount,
    runningCount: workingCount,
    hasWorking: workingCount > 0,
    hasWaiting: waitingCount > 0,
    hasDone: doneCount > 0,
    hasUnread: unread,
  };
}

/**
 * Visual precedence mirrors Orca: user attention wins over live work, live work wins over
 * retained notifications, and a completed-but-read agent is shown last.
 */
export function resolveActivityIndicator(summary: ActivitySummary | undefined): ActivityIndicatorState {
  if (!summary) return null;
  if (summary.hasWaiting) return "waiting";
  if (summary.hasWorking) return "working";
  if (summary.hasUnread) return "unread";
  if (summary.hasDone) return "done";
  return null;
}

export function activityStateToAgentState(state: TerminalActivityState): AgentState {
  if (state === "done") return "exited";
  return state;
}

import type { PaneDirection, PaneNode } from "../state/paneTree";

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  id: string;
  cwd: string;
  workspaceId: string;
  worktree: WorktreeIdentity | null;
  backendSessionId: string | null;
  lifecycle: TerminalLifecycle;
  ownerId?: string | null;
};

export type TerminalTab = {
  kind?: "terminal";
  id: string;
  label: string;
  sessionId: string;
  pinned?: boolean;
};

export type BrowserProfileId = "default" | "private";

export type LogicalRect = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type BrowserState = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  worktreePath?: string | null;
  profileId: BrowserProfileId;
  generation: number;
  url: string;
  title?: string | null;
  loading: boolean;
  canGoBack: boolean;
  canGoForward: boolean;
  zoomFactor: number;
  loadError?: string | null;
  visible: boolean;
};

export type BrowserTab = {
  kind: "browser";
  id: string;
  label: string;
  browserId: string;
  url: string;
  title?: string | null;
  loading?: boolean;
  canGoBack?: boolean;
  canGoForward?: boolean;
  pinned?: boolean;
};

export type WorkspaceTab = TerminalTab | BrowserTab;

export type CreateBrowserRequest = {
  workspaceId?: string | null;
  worktreePath?: string | null;
  url: string;
  profile?: BrowserProfileId;
  bounds?: LogicalRect;
  visible?: boolean;
};

export type BrowserSessionSummary = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  url: string;
  title?: string | null;
  visible: boolean;
};

export type Pane = {
  id: string;
  tabId: string;
};

export type SplitMode = "none" | "horizontal" | "vertical";

export type NestedSplit = {
  orientation: Exclude<SplitMode, "none">;
  tabId: string;
};

/**
 * The split arrangement inside a single terminal tab. This is intentionally separate
 * from TabGroupLayoutNode: Orca keeps terminal panes inside a tab and split tab groups
 * as two different layout layers.
 */
export type TabPaneLayout = {
  root: PaneNode;
  /** Leaf that receives keyboard focus inside this tab. */
  activeLeafId: string | null;
  /** Leaf temporarily zoomed to fill the tab, or `null` when every pane is visible. */
  expandedLeafId: string | null;
  /** Terminal session rendered by each leaf of `root`. */
  sessionIdsByLeafId: Record<string, string>;
};

export type TabGroup = {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
};

export type TabGroupLayoutNode =
  | { type: "group"; groupId: string }
  | {
      type: "split";
      direction: PaneDirection;
      first: TabGroupLayoutNode;
      second: TabGroupLayoutNode;
      ratio: number;
    };

export type LayoutState = {
  tabs: WorkspaceTab[];
  primaryTabId?: string | null;
  secondaryTabId?: string | null;
  split?: SplitMode;
  nestedSplit?: NestedSplit | null;
  /** Active tab in the currently focused tab group. */
  activeTabId: string | null;
  /** Terminal-pane tree owned independently by each tab. */
  layoutsByTabId: Record<string, TabPaneLayout>;
  /** Orca-style tab groups. Optional only for backwards-compatible persisted/test state. */
  tabGroups?: Record<string, TabGroup>;
  /** Split tree whose leaves are tab groups, not terminal panes. */
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
};

export type AgentState = "starting" | "working" | "waiting" | "exited" | "failed";

export type ActiveAgent = {
  id: string;
  name: string;
  task: string;
  state: AgentState;
  worktree: WorktreeIdentity | null;
  worktreePath: string;
  sessionId: string;
};

export type TerminalOutputPayload = {
  sessionId: string;
  data: string;
};

export type TerminalLifecyclePayload = {
  sessionId: string;
  state: "started" | "exited" | "failed";
  exitCode: number | null;
  reason: string | null;
};

export type WorktreeChangedPayload = {
  workspaceId: string;
  worktree: WorktreeIdentity;
  kind: "created" | "deleted" | "destructivelyDeleted" | "dirtyChanged" | "pruned";
};

export type NotificationSource = "agent-task-complete" | "terminal-bell" | "system";
export type NotificationAuthorization = "not-determined" | "denied" | "authorized" | "provisional" | "unknown";
export type NotificationPlatform = "macos" | "windows" | "linux" | "unknown";

export interface NotificationPermissionStatus {
  platform?: NotificationPlatform;
  supported?: boolean;
  authorization: NotificationAuthorization;
  alertsEnabled?: boolean | null;
  soundsEnabled?: boolean | null;
  requested?: boolean;
  authoritative?: boolean;
  canOpenSettings?: boolean;
  status?: string;
}

export interface NotificationPermissionRequest {
  granted: boolean;
  status?: NotificationPermissionStatus;
  error?: string | null;
}

export interface DispatchNotificationArgs {
  source?: NotificationSource | string;
  title?: string;
  body?: string;
  notificationId?: string;
  workspaceLabel?: string;
  worktreeLabel?: string;
  terminalTitle?: string;
  agentLabel?: string;
}

export interface DispatchNotificationResult {
  submitted?: boolean;
  delivered?: boolean;
  reason?: "permission-required" | "blocked-by-system" | "unsupported" | "backend-error" | string;
}

export interface NotificationProbeResult {
  outcome?: "submitted" | "ready" | "permission-required" | "blocked-by-system" | "unsupported" | "failed" | string;
  status?: NotificationPermissionStatus;
  testSubmitted?: boolean;
  success?: boolean;
}

export interface OpenSystemSettingsResult {
  opened: boolean;
  reason?: string | null;
}

export interface PlaySoundResult {
  played: boolean;
  reason?: string | null;
}

export interface PickedAudioFile {
  path: string;
  displayName?: string;
  extension?: string;
  sizeBytes?: number;
}

export type StructuredIpcError = {
  code: string;
  message: string;
  details?: Record<string, unknown>;
};

export interface PersistedWorktree {
  path: string;
  branch: string;
  head: string;
  isMain: boolean;
  isLocked: boolean;
}

export interface PersistedTab {
  id: string;
  sessionId: string;
  label: string;
  customTitle?: string;
  worktreePath: string;
  paneTree?: PaneNode;
  sessionIdsByLeafId?: Record<string, string>;
  activeLeafId?: string | null;
}

export interface PersistedTabGroup {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
}

export interface PersistedLayout {
  splitMode: string;
  primaryTabId: string | null;
  secondaryTabId: string | null;
  activeTabId: string | null;
  tabs: PersistedTab[];
  tabGroups?: PersistedTabGroup[];
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
}

export interface PersistedTerminalSession {
  sessionId: string;
  worktreePath: string;
  cwd: string;
  lastCommand?: string;
  recentScrollback?: string;
  createdAt: number;
}

export interface PersistedWorkspace {
  workspaceId: string;
  repoRoot: string;
  worktrees: PersistedWorktree[];
  activeWorktreePath: string | null;
  layout: PersistedLayout;
  terminalSessions: Record<string, PersistedTerminalSession>;
}

export interface PersistedWorkspaceSession {
  version: number;
  timestamp: number;
  activeWorkspaceId: string;
  workspaces: Record<string, PersistedWorkspace>;
}

